Import a template in lunora/auth/index.ts and render it with @lunora/mail's `renderEmail`, replacing the plain-text body the base `auth` item scaffolds:

```tsx
import { renderEmail } from "@lunora/mail";
import { ResetPasswordEmail } from "./emails";

sendResetPassword: async ({ url, user }) => {
    const { html, text } = await renderEmail(<ResetPasswordEmail url={url} />);
    await sendAuthEmail(env, { html, subject: "Reset your password", text, to: user.email });
},
```

Every template takes an optional `product` prop for the masthead. The file is yours — restyle it freely; it uses inline styles only because mail clients strip <style> blocks.
